async function checkOrder(){const session=new URL(location.href).searchParams.get('session_id');const button=document.getElementById('recheck');button.disabled=true;try{if(!session||!/^cs_[A-Za-z0-9_]+$/.test(session))throw Error('No valid order reference was provided.');const response=await fetch('/api/fulfillment?session_id='+encodeURIComponent(session),{cache:'no-store'});if(!response.ok)throw Error('The order is not ready for download. Checkout may be unavailable or payment may still be processing.');const data=await response.json();if(!data.ready||typeof data.downloadUrl!=='string')throw Error('Payment has not been verified.');const url=new URL(data.downloadUrl,location.href);if(url.origin!==location.origin||url.pathname!=='/api/download')throw Error('The download link could not be verified.');document.getElementById('download').href=url.href;document.getElementById('download').hidden=false;document.getElementById('fulfillment-status').textContent='The server verified this paid order. Download the toolkit and keep a private copy.';}catch(error){document.getElementById('fulfillment-status').textContent=error.message;}finally{button.disabled=false;}}
document.getElementById('recheck').addEventListener('click',checkOrder);checkOrder();
